using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Xml.Linq;
using CargoWise.RefDbRepo.TaiwanReferenceData.TurnkeyPlugInUpdateService;
using Moq;
using NUnit.Framework;

namespace CargoWise.RefDbRepo.TaiwanReferenceData.Test
{
	[TestFixture]
	public class TradeGroupUpdateInfoTest
	{
		class TradeGroupUpdateInfoForTest : TradeGroupUpdateInfo
		{
			public TradeGroupUpdateInfoForTest(updateInfoBean info, string filename) : base(info, filename)
			{
				this.BeforeExecuteEvent += TradeGroupUpdateInfoForTest_BeforeExecuteEvent;
			}

			private void TradeGroupUpdateInfoForTest_BeforeExecuteEvent()
			{
				SystemContext.Now = () => new DateTime(2019, 11, 14, 13, 44, 30);
			}

			protected override IWebClient GetWebClientWrapper()
			{
				var mock = new Mock<IWebClient>();
				byte[] responseTariffBytes = File.ReadAllBytes(Path.Combine(FolderHelper.GetBinFolder(), "doc/Tariff/TARIFF_3.txt"));
				string ftaCountriesBase64String = "";
				mock.Setup(x => x.DownloadData("http://192.118.118.3")).Returns(responseTariffBytes);
				mock.Setup(x => x.DownloadData("http://192.118.118.2")).Returns(Convert.FromBase64String(ftaCountriesBase64String));
				return mock.Object;
			}

			public new void GetAllCountries(string url)
			{
				base.GetAllCountries(url);
			}

			public new void GetWtoFtaCountries(string url)
			{
				base.GetWtoFtaCountries(url);
			}

			public new void GetLdcsAndSpecialCountries(string url)
			{
				base.GetLdcsAndSpecialCountries(url);
			}

			public new Dictionary<string, string> IsoCountries => base.IsoCountries;

			public new HashSet<string> EUCountryList => base.EUCountryList;

			public new List<RefCusTradeGroup> TradeGroupList => base.TradeGroupList;

		}


		[Test]
		public void TestProcessWtoFtaTable()
		{
			string base64StringHtml = "";
			var actualResult = TradeGroupUpdateInfoForTest.ProcessWtoFtaTable(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(base64StringHtml)));
			string expectedBase64String = "";
			Assert.AreEqual(Encoding.UTF8.GetString(Convert.FromBase64String(expectedBase64String)), actualResult);
		}

		[Test]
		public void TestGetAllCountries()
		{
			string countriesUrl = Path.Combine(FolderHelper.GetBinFolder(), "doc/TradeGroup/countries.xml");
			TradeGroupUpdateInfoForTest updateInfo = new TradeGroupUpdateInfoForTest(new updateInfoBean(), string.Empty);
			updateInfo.GetAllCountries(countriesUrl);
			Assert.AreEqual(440, updateInfo.IsoCountries.Count);
			Assert.AreEqual(28, updateInfo.EUCountryList.Count);
		}

		[Test]
		public void TestGetWtoFtaCountries()
		{
			string wtoFtaCountriesUrl = "http://192.118.118.2";
			string countriesUrl = Path.Combine(FolderHelper.GetBinFolder(), "doc/TradeGroup/countries.xml");
			TradeGroupUpdateInfoForTest updateInfo = new TradeGroupUpdateInfoForTest(new updateInfoBean(), string.Empty);
			updateInfo.GetAllCountries(countriesUrl);
			Assert.AreEqual(440, updateInfo.IsoCountries.Count);
			Assert.AreEqual(28, updateInfo.EUCountryList.Count);
			Assert.AreEqual(true, updateInfo.EUCountryList.Contains("DE"));
			Assert.AreEqual(true, updateInfo.EUCountryList.Contains("FR"));
			Assert.AreEqual(false, updateInfo.EUCountryList.Contains("CN"));
			updateInfo.GetWtoFtaCountries(wtoFtaCountriesUrl);
			Assert.AreEqual(29, updateInfo.TradeGroupList.Where(t => t.ZZA_TradeGroup == TradeGroup.FTA.ToString()).FirstOrDefault().Countries.Count);
			Assert.AreEqual(166, updateInfo.TradeGroupList.Where(t => t.ZZA_TradeGroup == TradeGroup.WTO.ToString()).FirstOrDefault().Countries.Count);
			Assert.AreEqual(true, updateInfo.TradeGroupList.Where(t => t.ZZA_TradeGroup == TradeGroup.WTO.ToString()).FirstOrDefault().Countries.Contains("TW"));
		}

		[Test]
		public void TestGetLdcsAndSpecialCountries()
		{
			string tariffColumn2Url = "http://192.118.118.3";
			string countriesUrl = Path.Combine(FolderHelper.GetBinFolder(), "doc/TradeGroup/countries.xml");
			TradeGroupUpdateInfoForTest updateInfo = new TradeGroupUpdateInfoForTest(new updateInfoBean(), string.Empty);
			updateInfo.GetLdcsAndSpecialCountries(tariffColumn2Url);
			Assert.AreEqual(47, updateInfo.TradeGroupList.Where(t => t.ZZA_TradeGroup == TradeGroup.LDC.ToString()).FirstOrDefault().Countries.Count);
			Assert.AreEqual(10, updateInfo.TradeGroupList.Where(t => t.ZZA_TradeGroup == TradeGroup.SPE.ToString()).FirstOrDefault().Countries.Count);
			Assert.AreEqual(10, updateInfo.TradeGroupList.Where(t => t.ZZA_TradeGroup != TradeGroup.FTA.ToString()
				&& t.ZZA_TradeGroup != TradeGroup.LDC.ToString()
				&& t.ZZA_TradeGroup != TradeGroup.SPE.ToString()).Count());
		}

		[Test]
		public void TestExecute()
		{
			string countriesUrl = Path.Combine(FolderHelper.GetBinFolder(), "doc/TradeGroup/countries.xml");
			string ftaCountriesUrl = "http://192.118.118.2";
			string tariffColumn2Url = "http://192.118.118.3";
			string fileName = Path.Combine(Utility.TempDirectory, string.Format("{0}.xml", Guid.NewGuid().ToString()));
			var info = new updateInfoBean();
			info.downloadURL = string.Join(";", new string[] { countriesUrl, ftaCountriesUrl, tariffColumn2Url });
			var updateInfo = new TradeGroupUpdateInfoForTest(info, fileName);
			updateInfo.Run();
			var actualXml = XDocument.Load(fileName);
			string path = Path.Combine(FolderHelper.GetBinFolder(), "doc/TradeGroup/TradeGroup.xml");
			var expectedXml = XDocument.Load(path);
			Assert.AreEqual(expectedXml.ToString(), actualXml.ToString());
			File.Delete(fileName);
		}

		[Test]
		[SetCulture("en-US")]
		public void TestExecuteWhenUS()
		{
			TestExecute();
		}

		[Test]
		[SetCulture("fr-FR")]
		public void TestExecuteWhenFR()
		{
			TestExecute();
		}
	}
}
